fn a_property_of_an_object_with_none_of_its_own_is_what_get_finds() {
    std::thread::Builder::new()
        .stack_size(8 << 20)
        .spawn(properties_that_objects_inherit)
        .expect("thread")
        .join()
        .expect("checks");
}

