fn a_property_read_leaves_the_register_as_found_or_as_the_general_way_wants_it() {
    std::thread::Builder::new()
        .stack_size(8 << 20)
        .spawn(reads_into_the_result_register)
        .expect("thread")
        .join()
        .expect("checks");
}

