fn map_and_filter_write_plain_elements_as_the_steps_define_them() {
    std::thread::Builder::new()
        .stack_size(8 << 20)
        .spawn(arrays_mapped_and_filtered)
        .expect("thread")
        .join()
        .expect("checks");
}

