fn a_property_that_an_exotic_object_inherits_is_what_the_steps_give() {
    std::thread::Builder::new()
        .stack_size(8 << 20)
        .spawn(inherited_properties_of_exotic_objects)
        .expect("thread")
        .join()
        .expect("checks");
}

